package pe.com.dentalamericana.treatment;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="evoluciones_tratamiento")public class TreatmentEvolution{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="plan_item_id",nullable=false)private Long itemId;@Column(name="atencion_id")private Long encounterId;@Column(nullable=false)private Instant fecha;@Column(name="procedimiento_realizado",nullable=false,columnDefinition="TEXT")private String procedure;@Column(columnDefinition="TEXT")private String observaciones;@Column(name="proxima_sesion")private LocalDate nextSession;@Column(name="aprobado_por",nullable=false)private Long approvedBy;@Column(name="creado_en",nullable=false,updatable=false)private Instant createdAt;protected TreatmentEvolution(){}public TreatmentEvolution(Long itemId,Long encounterId,String procedure,String observations,LocalDate nextSession,Long actor){this.itemId=itemId;this.encounterId=encounterId;this.procedure=procedure;this.observaciones=observations;this.nextSession=nextSession;this.approvedBy=actor;this.fecha=Instant.now();}@PrePersist void create(){createdAt=Instant.now();}public Long getId(){return id;}public Long getItemId(){return itemId;}public Long getEncounterId(){return encounterId;}public Instant getDate(){return fecha;}public String getProcedure(){return procedure;}public String getObservations(){return observaciones;}public LocalDate getNextSession(){return nextSession;}public Long getApprovedBy(){return approvedBy;}}
